// Receiving shares the inventory ledger; quantities belong to a product line, not each container.
flavors.push('Abacaxi');skus.push({code:'YOL-004',flavor:'Abacaxi'});
let supplies=[{code:'MAT-001',name:'Caixa de envio',unit:'un',category:'Embalagem'},{code:'MAT-002',name:'Insert / encarte',unit:'un',category:'Material de envio'},{code:'MAT-003',name:'Aromatizante (exemplo)',unit:'L',category:'Insumo'}],materialStock=[],receivingRow=0;
const baseRender=render,baseBoard=renderBoard,baseAddMaster=addMaster;
function productCatalog(){return [...skus.map(s=>({code:s.code,name:'YOLO Pop · '+s.flavor,flavor:s.flavor,kind:'pop',unit:'un'})),...supplies.map(s=>({...s,kind:'material'}))]}
function receiptRowsHTML(n){return `<section class="receipt-item" data-receipt-row="${n}"><div class="row"><strong>Item do recebimento</strong><button type="button" onclick="this.closest('[data-receipt-row]').remove()">Remover item</button></div><div class="receipt-grid"><label>Produto / SKU<select name="product-${n}" onchange="updateReceiptRow(${n})">${productCatalog().map(p=>`<option value="${esc(p.code)}">${esc(p.name)} · ${esc(p.code)}</option>`).join('')}</select></label><label>Quantidade total<input name="qty-${n}" type="number" min="1" step="1" required placeholder="235"><small id="unit-${n}" class="unit-hint">Unidade: un</small></label><label>Lote<input name="lot-${n}" required placeholder="Lote do fabricante"></label></div><label>Códigos das caixas retornáveis <span id="box-required-${n}">(obrigatório)</span><textarea name="codes-${n}" required placeholder="PRETA-001, PRETA-007, PRETA-030" onkeydown="if(event.key==='Enter'){event.stopPropagation()}"></textarea></label><div class="scanhelp">Digite códigos separados por vírgula ou escaneie com leitor que preenche texto, um código por linha. A quantidade acima é o total do produto em todas estas caixas. Câmera do celular ainda não conectada.</div></section>`}
function addReceiptRow(){const n=++receivingRow;$('receipt-items').insertAdjacentHTML('beforeend',receiptRowsHTML(n));return n}
function updateReceiptRow(n){const f=$('receipt-form'),p=productCatalog().find(p=>p.code===f.elements['product-'+n].value),pop=p.kind==='pop';f.elements['codes-'+n].required=pop;f.elements['lot-'+n].required=pop;f.elements['qty-'+n].step=p.unit==='un'?'1':'0.001';f.elements['qty-'+n].min=p.unit==='un'?'1':'0.001';$('unit-'+n).textContent='Unidade: '+p.unit;$('box-required-'+n).textContent=pop?'(obrigatório)':'(opcional)'}
function receivingPage(){const today=new Date(),date=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');return `<form id="receipt-form" class="receipt-form" onsubmit="submitReceipt(event)"><div class="notice">Recebimento em ${esc(locations[0])}. Registre todos os produtos da mesma nota fiscal. Quantidades ficam em análise até a conferência.</div><section class="panel"><h2>1. Documento de entrada</h2><div class="receipt-grid">${input('nf','Número da nota fiscal')}${input('supplier','Fornecedor')}${input('date','Data de recebimento',date,'date')}</div></section><h2>2. Produtos e caixas</h2><div id="receipt-items">${receiptRowsHTML(++receivingRow)}</div><button type="button" onclick="addReceiptRow()">＋ Adicionar produto</button><p id="receipt-error" class="receipt-error" role="alert"></p><div class="receipt-footer"><button type="button" onclick="go('Início')">Voltar</button><button type="submit" class="primary">Registrar recebimento</button></div></form>`}
function normalizeBoxCode(s){return s.trim().toUpperCase().replace(/[\s_-]+/g,'-')}
function validateReceipt(d){if(!d.nf?.trim()||!d.supplier?.trim()||!d.date)throw Error('Preencha os dados da nota fiscal.');if(!d.items.length)throw Error('Adicione pelo menos um produto.');const used=new Set();return d.items.map(item=>{const p=productCatalog().find(p=>p.code===item.code),qty=Number(item.qty);if(!p)throw Error('Produto não cadastrado.');if(!Number.isFinite(qty)||qty<=0||(p.unit==='un'&&!Number.isInteger(qty)))throw Error('Informe uma quantidade válida para '+p.name+'.');if(p.kind==='pop'&&!item.lot.trim())throw Error('Informe o lote de '+p.name+'.');const codes=item.codes.split(/[,;\r\n]+/).map(normalizeBoxCode).filter(Boolean);if(p.kind==='pop'&&!codes.length)throw Error('Informe as caixas de '+p.name+'.');for(const c of codes){if(used.has(c))throw Error('Caixa repetida neste recebimento: '+c+'. Use um código único por caixa.');used.add(c)}return {...p,qty,lot:item.lot.trim(),codes}})}
function commitReceipt(d){const items=validateReceipt(d),receiptId='REC-'+String(notes.length+1).padStart(3,'0');const note={id:receiptId,nf:d.nf.trim(),supplier:d.supplier.trim(),date:d.date,items};notes.push(note);for(const p of items){if(p.kind==='pop')boxes.push({...mk(uniqueStockId('CX-'),p.flavor,p.qty,0,''),sku:p.code,lot:p.lot,date:d.date,receiptId,sourcePackages:[...p.codes]});else materialStock.push({id:'MAT-REC-'+String(++seq),sku:p.code,name:p.name,unit:p.unit,qty:p.qty,lot:p.lot,loc:0,analysis:true,date:d.date,receiptId,sourcePackages:[...p.codes]});for(const code of p.codes){let box=packages.find(b=>normalizeBoxCode(b.id)===code);if(!box){box={id:code};packages.push(box)}Object.assign(box,{location:locations[0],receiptId,product:p.name})}}log(`${receiptId} · NF ${note.nf}: ${items.map(i=>`${i.name}, ${i.qty} ${i.unit}, ${i.codes.length} caixas`).join('; ')}`);return note}
function submitReceipt(e){e.preventDefault();const f=e.target,fd=new FormData(f),items=[...f.querySelectorAll('[data-receipt-row]')].map(el=>{const n=el.dataset.receiptRow;return {code:fd.get('product-'+n),qty:fd.get('qty-'+n),lot:fd.get('lot-'+n)||'',codes:fd.get('codes-'+n)||''}});try{commitReceipt({nf:fd.get('nf'),supplier:fd.get('supplier'),date:fd.get('date'),items});go('Notas fiscais');toast('Recebimento registrado. Produtos em análise.')}catch(err){$('receipt-error').textContent=err.message}}
receive=function(){go('Recebimento')};
render=function(){baseRender();if(view==='Início'){$('app').querySelector('.tiles').insertAdjacentHTML('afterbegin','<button class="tile receive-tile" onclick="receive()"><span>↓</span>Recebimento<small>Primeiro passo · receber produtos, insumos e embalagens</small></button>')}
if(view==='Recebimento'){$('app').innerHTML='<div class="heading"><div><h1>Recebimento</h1><p>Uma nota fiscal · vários produtos · todas as caixas</p></div></div>'+receivingPage()}
if(view==='Notas fiscais'){$('app').querySelector('.panel').innerHTML='<h2>Notas fiscais de recebimento</h2>'+(notes.length?notes.map(n=>`<section class="row receipt-summary"><strong>${esc(n.id)} · NF ${esc(n.nf)} · ${esc(n.supplier)}</strong><small>${esc(n.date)} · ${n.items.length} itens</small><ul>${n.items.map(i=>`<li><strong>${esc(i.name)} · ${i.qty} ${esc(i.unit)}</strong><small>${esc(i.code)}${i.lot?' · Lote '+esc(i.lot):''}</small><small>Caixas: ${i.codes.length?i.codes.map(esc).join(', '):'Sem caixa retornável'}</small></li>`).join('')}</ul></section>`).join(''):'<p>Nenhuma nota nesta sessão. Registre seu primeiro recebimento.</p>')}
if(view==='Cadastros')$('app').insertAdjacentHTML('beforeend','<section class="panel"><div class="row"><h2>Materiais e insumos</h2><button onclick="addSupply()">＋ Cadastrar material</button></div>'+supplies.map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(p.category)} · ${esc(p.unit)}</small></div></div>`).join('')+'</section>');
if(view==='Embalagens')$('app').insertAdjacentHTML('beforeend','<section class="panel"><h2>Materiais de embalagem e insumos recebidos</h2>'+(materialStock.length?materialStock.map(m=>`<div class="row"><div><strong>${esc(m.name)} · ${m.qty} ${esc(m.unit)}</strong><small>${esc(locations[m.loc])} · ${m.blocked?'Bloqueado':m.analysis?'Em análise':'Disponível'}</small></div><button onclick="materialDetail('${m.id}')">Abrir</button></div>`).join(''):'<p>Caixas de envio, encartes e outros materiais aparecerão aqui após o recebimento.</p>')+'</section>')};
renderBoard=function(){baseBoard();let section=$('materials-section');if(!section){$('board').insertAdjacentHTML('afterend','<section id="materials-section" class="material-board"></section>');section=$('materials-section')}const list=materialStock.filter(m=>(m.name+' '+m.sku+' '+m.lot).toLowerCase().includes(filter.toLowerCase())&&!stateFilter);section.innerHTML='<h2>Materiais e insumos</h2><p>Saldo por produto e unidade. Separado das quantidades de pops.</p><div class="board">'+locations.map((l,i)=>{const ms=list.filter(m=>m.loc===i);return `<section class="column"><div class="colhead">${esc(l)} <span>${ms.length}</span></div>${ms.map(m=>`<button class="card" style="width:100%;text-align:left" onclick="materialDetail('${m.id}')"><div class="cardtop">${esc(m.sku)}</div><h3>${esc(m.name)}</h3><span class="tag">${m.blocked?'Bloqueado':m.analysis?'Em análise':'Disponível'}</span><div class="qty"><strong>${m.qty} ${esc(m.unit)}</strong></div><div class="boxmeta">${esc(m.receiptId)} · ${esc(m.lot||'Sem lote')}</div></button>`).join('')||'<div class="empty">Nenhum material</div>'}</section>`}).join('')+'</div>'};
function materialDetail(id){const m=materialStock.find(m=>m.id===id);openForm(m.name,`<p>${m.qty} ${esc(m.unit)} · ${esc(m.sku)}</p>`+select('loc','Local',locations,m.loc)+select('status','Conferência',['Em análise','Disponível'],m.analysis?0:1)+`<label>Retirar quantidade (${esc(m.unit)})<input name="withdraw" type="number" value="0" min="0" step="${m.unit==='un'?'1':'0.001'}" required></label>`,d=>{const q=Number(d.withdraw);if(!Number.isFinite(q)||q<0||q>m.qty||(m.unit==='un'&&!Number.isInteger(q)))throw Error('Quantidade inválida.');if(q&&d.status==='0')throw Error('Confirme a conferência antes de retirar.');m.qty=Number((m.qty-q).toFixed(3));m.loc=+d.loc;m.analysis=d.status==='0';log(`${m.sku}: saldo ${m.qty} ${m.unit}, ${locations[m.loc]}, ${m.analysis?'em análise':'disponível'}`)})}
function addSupply(){openForm('Cadastrar material ou insumo',input('code','SKU')+input('name','Nome')+select('category','Categoria',['Embalagem','Material de envio','Insumo','Outro'])+select('unit','Unidade',['un','kg','L','m']),d=>{const code=d.code.trim(),name=d.name.trim();if(!code||!name||productCatalog().some(p=>p.code.toUpperCase()===code.toUpperCase()))throw Error('Informe nome e SKU único.');supplies.push({code,name,category:['Embalagem','Material de envio','Insumo','Outro'][+d.category],unit:['un','kg','L','m'][+d.unit]});log('Material cadastrado: '+name)})}
view='Início';render();
